static inline void aiForwardPass(const float* x, float* out) {
  // layer 0: 17->32  ReLU
  float h0[32];
  for (int j = 0; j < 32; j++) {
    float s = AI_B0[j];
    for (int k = 0; k < 17; k++) s += x[k] * AI_W0[k * 32 + j];
    h0[j] = s > 0.0f ? s : 0.0f;
  }
  // layer 1: 32->16  ReLU
  float h1[16];
  for (int j = 0; j < 16; j++) {
    float s = AI_B1[j];
    for (int k = 0; k < 32; k++) s += h0[k] * AI_W1[k * 16 + j];
    h1[j] = s > 0.0f ? s : 0.0f;
  }
  // layer 2: 16->8  ReLU
  float h2[8];
  for (int j = 0; j < 8; j++) {
    float s = AI_B2[j];
    for (int k = 0; k < 16; k++) s += h1[k] * AI_W2[k * 8 + j];
    h2[j] = s > 0.0f ? s : 0.0f;
  }
  // layer 3: 8->2  softmax
  float logits[2];
  for (int j = 0; j < 2; j++) {
    float s = AI_B3[j];
    for (int k = 0; k < 8; k++) s += h2[k] * AI_W3[k * 2 + j];
    logits[j] = s;
  }
  // softmax
  float mL = logits[0];
  for (int i = 1; i < 2; i++) if (logits[i] > mL) mL = logits[i];
  float sumE = 0.0f;
  for (int i = 0; i < 2; i++) { out[i] = expf(logits[i] - mL); sumE += out[i]; }
  for (int i = 0; i < 2; i++) out[i] /= sumE;
}
